    Lemma ufi_fin : forall (pc0 : Z) (payf : bvmap 5 word -> word -> word) msF mo mc m1 (sx : as_St H) (r : rv) Fx fcx pad mw bw ew xg j6 f0 (p' : Z) (pw : word)
        (pb : bptr) (Bb cap : Z) (errv1 : word),
      let st1 := mkVS (Some (pb, Bb, 24 * cap)) cap (vs_items (ps_vs ps0)) 0 (vs_temp (ps_vs ps0)) in
