    Lemma pushi_full : forall (pc0 : Z) (payf : bvmap 5 word -> word -> word) msF mo mc (r : rv) Fx fcx pad mw bw ew xg j6 f0 (p' : Z) (pw : word),
      uf_seg 2 pc0 0x1044a4 (fun rq w => rs4 rq = w) payf (fun _ w => w) -> 0 <= pc0 < 2^64 -> pc0 mod 2 = 0 ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xf2b78) fcx None mc (seg_rom asegs) -> frm0 fcx ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw pad mw bw ew xg (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      rsp r = spw -> rgp r = gp -> rtp r = tp -> rs0 r = a0 -> rs1 r = Z_to_bv 64 p' -> rra r = Z_to_bv 64 pc0 -> ra0 r = a0 ->
      rs2 r = Z_to_bv 64 (pa + 24) -> rs3 r = Z_to_bv 64 (sh8 (pa + 24)) -> rs4 r = pw -> rs5 r = Z_to_bv 64 2147450880 ->
      rs6 r = s6 -> rs7 r = s7 -> rs8 r = s8 -> rs9 r = s9 -> rs10 r = s10 -> rs11 r = s11 ->
      vs_n (ps_vs ps0) = vs_cap (ps_vs ps0) -> p < p' <= e ->
