    Lemma bpushi_fin : forall msF mo mc (r : rv) Fx fcx pad mw bw ew xg j6 f0 (p' : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103d68) fcx None mc (seg_rom asegs) -> frm0 fcx ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw pad mw bw ew xg (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> p < p' <= e ->
