    Lemma uh_full : forall msF mo mc (r : rv) Fx fcx pad mw bw ew xg j6 f0 (p' : Z) (pw s4x s3x s2x s0x : word),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xf2b78) fcx None mc (seg_rom asegs) -> frm0 fcx ->
      nst mc -> stk asegs mc lo (bv_unsigned spw + -48) ->
      uframe mc spw pad mw bw ew xg (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      rw_cells asegs mc (bv_unsigned spw + -48) [C8 s4x; C8 s3x; C8 s2x; C8 (Z_to_bv 64 p'); C8 s0x; C8 (Z_to_bv 64 0x104184)] ->
      rsp r = Z_to_bv 64 (bv_unsigned spw + -48) -> rgp r = gp -> rtp r = tp -> rs2 r = a0 -> rs1 r = pw -> rra r = Z_to_bv 64 0xfd960 -> ra0 r = a0 ->
      rs0 r = Z_to_bv 64 (pa + 24) -> rs3 r = Z_to_bv 64 (sh8 (pa + 24)) -> rs4 r = Z_to_bv 64 2147450880 -> rs5 r = Z_to_bv 64 2147450880 ->
      rs6 r = s6 -> rs7 r = s7 -> rs8 r = s8 -> rs9 r = s9 -> rs10 r = s10 -> rs11 r = s11 ->
      vs_n (ps_vs ps0) = vs_cap (ps_vs ps0) -> p < p' <= e ->
