    Lemma fin_fin : forall msF mo mc (r : rv) Fx pad (mw : word) (bc xc xn : Z) j6 f0 (p' : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x104258) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw pad mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> p < p' <= e -> -2^31 < bc < 2^31 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
      (xn = 0 /\ bc + xc < 2^31 \/ xn = 1 /\ -2^31 <= bc - xc) ->
      as_SR H POST (mkCfg msF mo).
Proof.
