    Lemma leaf16_frame : forall mc m1,
      munch [(bv_unsigned spw + -16, bv_unsigned spw)]%Z mc m1 -> wmono asegs mc m1 -> mem_inv asegs m1 ->
      nst mc -> pinb mc p0 e inb -> pshb mc p0 e ->
