    Lemma bigx_fin : forall msF mo mc (r : rv) Fx pad (mw bw : word) (a bc : Z) j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103bac) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw bw (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> ra3 r = Z_to_bv 64 a -> rs1 r = Z_to_bv 64 (a + 1) -> rt1 r = zxb (inb (a + 1)) -> ra4 r = Z_to_bv 64 bc ->
      p + 1 <= a -> a + 1 < e -> 1 <= bc -> bc + p <= e ->
      as_SR H POST (mkCfg msF mo).
Proof.
