    (* [comment removed for export] *)
    Lemma fcd_fin : forall msF mo mc (r : rv) Fx pad (mw : word) (q nd k2 : Z) j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103c90) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs3 r = Z_to_bv 64 p -> rs1 r = Z_to_bv 64 q -> rs4 r = Z_to_bv 64 nd -> ra0 r = Z_to_bv 64 k2 ->
      p + 2 <= q <= p + 16 -> p + 33 <= e -> 1 <= nd <= 15 -> 0 <= k2 <= 16 ->
