    Lemma il_loop : forall (i : Z) msF mo mc (r : rv) Fx pad (mw mcw : word) (b : Z) j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103abc) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw pad mcw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 f0 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> ra0 r = Z_to_bv 64 b -> ra2 r = Z_to_bv 64 i -> ra1 r = mw -> rs3 r = Z_to_bv 64 p -> ra3 r = Z_to_bv 64 9 -> ra4 r = Z_to_bv 64 1844674407370955161 -> ra5 r = Z_to_bv 64 2 -> ra6 r = Z_to_bv 64 54 -> ra7 r = Z_to_bv 64 10 ->
      p + 1 <= b -> 0 <= i -> b + i < e ->
      as_SR H POST (mkCfg msF mo).
Proof.
